package com.aistock.market.statistics;
import com.aistock.common.*;import com.aistock.market.security.*;import com.fasterxml.jackson.databind.ObjectMapper;import java.util.*;import java.time.*;import jakarta.servlet.http.Cookie;import org.junit.jupiter.api.Test;import org.springframework.test.web.servlet.setup.MockMvcBuilders;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
class MarketStatisticsAccessTest {
 @Test void adminOnlyAndSafeErrorMapping()throws Exception{var repo=mock(MarketStatisticsRepository.class);when(repo.summary(any(),anyInt(),anyInt(),any())).thenReturn(new MarketStatisticsRecords.MarketSummary(StatisticsMetaForTest(),"CURRENT_HEADS","0","0",List.of(),false));var identity=mock(SessionIdentityClient.class);when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new SessionIdentityClient.Identity(UUID.randomUUID().toString(),"ADMIN",false,1),"test"));
 var mvc=MockMvcBuilders.standaloneSetup(new MarketStatisticsController(repo,Clock.fixed(MarketStatisticsMysqlTest.NOW,ZoneOffset.UTC))).setControllerAdvice(new ApiExceptionHandler()).addFilters(new AdminStatisticsAccessFilter(identity,"server-test",new ObjectMapper().findAndRegisterModules())).build();var path="/api/v1/admin/statistics/market";var cookie=new Cookie("AISTOCK_SESSION","admin");
 mvc.perform(get(path)).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","no-store"));mvc.perform(get(path).cookie(cookie)).andExpect(status().isOk());mvc.perform(get(path).cookie(cookie,cookie)).andExpect(status().isUnauthorized());
 when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new SessionIdentityClient.Identity(UUID.randomUUID().toString(),"USER",false,1),"test"));mvc.perform(get(path).cookie(cookie).header("X-Role","ADMIN")).andExpect(status().isForbidden());
 when(identity.resolve(any(),anyString())).thenReturn(ApiResponse.success(new SessionIdentityClient.Identity("bad","ADMIN",false,-1),"test"));mvc.perform(get(path).cookie(cookie)).andExpect(status().isServiceUnavailable());verify(repo,times(1)).summary(any(),anyInt(),anyInt(),any());
 }
 static com.aistock.common.statistics.StatisticsMeta StatisticsMetaForTest(){return com.aistock.common.statistics.StatisticsMeta.of(MarketStatisticsMysqlTest.window(),MarketStatisticsMysqlTest.NOW);}
}
